actions.script:
const term = String(ec.web.parameters.term || '').trim()
const selected = String(ec.web.parameters.value || '').trim()
let out = []
if (selected && !term) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', selected).disableAuthz().one()
    if (account) out = [{value: account.userId, label: account.userFullName || account.username}]
} else {
    const found = ec.service.sync().name('org.moqui.comms.CommsServices.search#Users').parameters({term, limit: 20}).call() || {}
    out = Array.from(found.userList || []).map((user) => ({value: user.value, label: user.label}))
}
ec.web.sendJsonResponse(out)

const term = String(ec.web.parameters.term || '').trim().toLowerCase()
const selected = String(ec.web.parameters.value || '').trim()
const L = (text) => ec.l10n.localize(text)
const options = ec.service.sync().name('org.moqui.call.IvrServices.get#CallTargetOptions').requireNewTransaction(true).disableAuthz().call() || {}
ec.message.clearErrors()
let out = [{value: 'CtgEnd:', label: L('End the call')}, {value: 'CtgRepeat:', label: L('This menu again')}]
const add = (type, prefix, list) => { for (const o of Array.from(list || [])) out.push({value: type + ':' + o.key, label: L(prefix) + ': ' + o.text}) }
add('CtgMenu', 'Menu', options.menuList)
add('CtgQueue', 'Queue', options.queueList)
add('CtgGroup', 'Ring group', options.groupList)
add('CtgVoicemail', 'Voicemail', options.boxList)
if (selected && !term && selected.startsWith('CtgUser:')) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', selected.slice(8)).disableAuthz().one()
    if (account) out.push({value: selected, label: L('User') + ': ' + (account.userFullName || account.username)})
} else if (term) {
    const found = ec.service.sync().name('org.moqui.comms.CommsServices.search#Users').parameters({term, limit: 20}).call() || {}
    for (const user of Array.from(found.userList || [])) out.push({value: 'CtgUser:' + user.value, label: L('User') + ': ' + user.label})
}
if (selected && !term) out = out.filter((o) => o.value === selected)
else if (term) out = out.filter((o) => o.label.toLowerCase().includes(term))
ec.web.sendJsonResponse(out.slice(0, 60))
